import{z as n,x as o,o as e,c as d,q as t,j as i,D as B,d as A,s as r,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"容错与弹性训练","description":"","frontmatter":{"title":"容错与弹性训练","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-fault-elastic.md","filePath":"llm/dist-fault-elastic.md","lastUpdated":1791063341000}'),D={name:"llm/dist-fault-elastic.md"};function C(p,E,h,m,F,c){const l=o("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="容错与弹性训练" tabindex="-1">容错与弹性训练 <a class="header-anchor" href="#容错与弹性训练" aria-label="Permalink to &quot;容错与弹性训练&quot;">​</a></h1><div class="epigraph"><p>万卡规模下，故障是期望事件而不是事故；容错设计的产出物是恢复时间，不是「我们没坏」。</p><footer>—— 据 Athlur 等 2022 与 Jiang 等 2024 整理</footer></div><p><a href="/llm/dist-cross-dc">上一课</a>把训练摊到广域，故障域随之变大。主干课的<a href="/llm/large-scale-failure-rate">万卡训练的故障率</a>给了 MTBF、MTTR 与丢失窗口的账，<a href="/llm/elastic-training">弹性训练与掉卡</a>给了掉卡后的计划选择；本课深钻整条容错链路：检测、隔离、恢复、记账四段怎么接，以及弹性枚举的约束。不重讲检查点格式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单点故障经集体通信放大成全组挂起：一张卡的 ECC 错、一条链路的抖动、一个主机的内存故障，表象都是 NCCL 超时与全组 hang。恢复的每一秒都是丢掉的有效算力，而恢复本身有自己的坑：状态没对齐（数据游标、RNG、学习率调度器各回各的家）、按新世界大小重切分片出错、恢复后头几分钟利用率骤降（页缓存冷、通信库冷启动、文件系统缓存重建）。容错不是「有检查点」一句话，是四段链路每一段都有明确产物。</p><p><span class="marginnote">两个缩写先翻译：MTBF 是平均无故障时间——两次故障之间平均撑多久；MTTR 是平均恢复时间——从坏到好平均要多久。万卡规模下 MTBF 常常以小时计，所以「一天修几次」是排班里的常规项，不是事故。</span></p><h3 id="四段链路" tabindex="-1">四段链路 <a class="header-anchor" href="#四段链路" aria-label="Permalink to &quot;四段链路&quot;">​</a></h3><p>检测：按域分层设超时——进程组级、节点级、交换机级——把「谁先超时」变成定位信息而不是噪音；可见故障与静默损坏分开走，静默损坏靠校验和抽查与可疑检查点回退，不能指望 ECC 抓住一切。隔离：坏节点退出，进程组按新世界大小重建，坏槽位登记退役，防止同槽位反复咬人。恢复：从最近合法快照起，快照必须同时含参数、优化器状态与数据游标，全局完成标志是各分片的 AND——缺一个就整体作废；按新网格重切分片时按弹性枚举选最大可行世界。记账：token 游标对齐、丢失窗口入账、事件进故障台账，让下一次 MTBF 的估计有数据。</p><p><span class="marginnote">「全局完成标志是各分片的 AND」意思是：每个分片都写完，快照才算合法，缺一个就整体作废。初学者容易看到主分片文件在就拿来恢复——恢复到一半发现缺片，损失的时间比不做恢复还多。</span></p><p><span class="marginnote">期望丢失约等于检查点间隔的一半加检测时间加恢复时间。间隔加密，丢失少了，但 I/O 与让路保存吃掉吞吐；间隔放疏，一次故障吃掉半天。最优间隔是有效算力的极大值点，随 MTBF 与存储带宽移动，不是拍脑袋的固定值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>弹性枚举是链路的约束层：合法世界大小是离散集——EP 整除专家数优先，TP 整除头数且要装得进 NVLink 域，PP 不超过层数，DP 承接剩余——掉卡后从集合里选不超过现存设备的最大值，而不是恢复原配置硬等。恢复后的冷启动要专门处理：先跑几个空步或小步让缓存与通信路径热起来，再回到全速，否则恢复后的利用率曲线会让人误判二次故障。事件语义要写进日志的固定字段：时间、域、根因分类、丢失窗口、新世界大小——这五列齐了，故障率课的账才算得动。</p>',12)),(e(),i(s,null,{default:B(()=>[r(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AVAIL%5B%22%E6%8E%89%E5%8D%A1%E5%90%8E%E7%8E%B0%E5%AD%98%E8%AE%BE%E5%A4%87%2C%20%E4%BE%8B%20504%20%E5%8F%B0%22%5D%20--%3E%20ENUM%5B%22%E6%8C%89%E4%B8%89%E9%81%93%E7%BA%A6%E6%9D%9F%E6%9E%9A%E4%B8%BE%E5%90%88%E6%B3%95%E4%B8%96%E7%95%8C%E5%A4%A7%E5%B0%8F%22%5D%0A%20%20subgraph%20CONS%5B%22%E6%95%B4%E9%99%A4%E7%BA%A6%E6%9D%9F%E6%98%AF%E7%A1%AC%E7%9A%84%22%5D%0A%20%20%20%20C1%5B%22EP%20%E6%95%B4%E9%99%A4%E4%B8%93%E5%AE%B6%E6%95%B0%22%5D%0A%20%20%20%20C2%5B%22TP%20%E6%95%B4%E9%99%A4%E5%A4%B4%E6%95%B0%2C%20%E4%B8%94%E8%A3%85%E8%BF%9B%20NVLink%20%E5%9F%9F%22%5D%0A%20%20%20%20C3%5B%22PP%20%E4%B8%8D%E8%B6%85%E8%BF%87%E5%B1%82%E6%95%B0%22%5D%0A%20%20end%0A%20%20ENUM%20--%3E%20C1%0A%20%20C1%20--%3E%20C2%0A%20%20C2%20--%3E%20C3%0A%20%20C3%20--%3E%20DP%5B%22DP%20%E6%89%BF%E6%8E%A5%E5%89%A9%E4%BD%99%E5%8D%A1%E6%95%B0%2C%20%E5%BE%97%E6%A0%BC%E7%82%B9%E9%9B%86%22%5D%0A%20%20DP%20--%3E%20PICK%5B%22%E9%80%89%E4%B8%8D%E8%B6%85%E8%BF%87%20504%20%E7%9A%84%E6%9C%80%E5%A4%A7%E6%A0%BC%E7%82%B9%22%5D%0A%20%20PICK%20--%3E%20IDLE%5B%22%E5%A4%9A%E4%BD%99%E5%8D%A1%E9%97%B2%E7%BD%AE%2C%20%E4%B8%8D%E7%A1%AC%E5%87%91%E7%A0%B4%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("为什么丢失窗口由检查点间隔决定：故障在两次快照之间均匀发生时，期望回退是间隔的一半，加上检测与恢复的固定时间，构成一次故障的总损失；损失率乘上故障频率，就是有效算力的折损项。保存频率加密的代价不止 I/O：同步保存会在 step 边界插出停顿，异步保存（口径见"),a("a",{href:"/llm/async-checkpointing"},"异步检查点"),A("）把刷盘挪出关键路径，但进行中的保存不可无界堆积。为什么弹性枚举是离散的：每一维并行的整除约束是硬的，世界大小只能落在格点上；掉卡发生在格点之间时，宁可让一部分卡闲置，也不让整除约束破产。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"代个数字感受量级：检查点间隔 30 分钟，期望回退就是 15 分钟；加上检测 5 分钟、恢复 10 分钟，一次故障平均吃掉全组约 30 分钟算力。若故障平均一天两次，等于每天蒸发一小时的整机时——这就是为什么间隔值得精算而不是拍脑袋。")],-1)),(e(),i(s,null,{default:B(()=>[r(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E6%95%85%E9%9A%9C%E5%8F%91%E7%94%9F%22%5D%20--%3E%20DET%7B%22%E6%A3%80%E6%B5%8B%3A%20%E5%88%86%E5%9F%9F%E8%B6%85%E6%97%B6%22%7D%0A%20%20DET%20--%3E%7C%E5%8F%AF%E8%A7%81%E6%95%85%E9%9A%9C%7C%20ISO%5B%22%E9%9A%94%E7%A6%BB%3A%20%E9%80%80%E8%8A%82%E7%82%B9%2C%20%E9%80%80%E5%BD%B9%E5%9D%8F%E6%A7%BD%E4%BD%8D%22%5D%0A%20%20DET%20--%3E%7C%E7%96%91%E4%BC%BC%E9%9D%99%E9%BB%98%E6%8D%9F%E5%9D%8F%7C%20VER%5B%22%E6%A0%A1%E9%AA%8C%E6%8A%BD%E6%9F%A5%2C%20%E5%8F%AF%E7%96%91%E6%A3%80%E6%9F%A5%E7%82%B9%E5%9B%9E%E9%80%80%22%5D%0A%20%20ISO%20--%3E%20RECO%5B%22%E6%81%A2%E5%A4%8D%3A%20%E6%9C%80%E8%BF%91%E5%90%88%E6%B3%95%E5%BF%AB%E7%85%A7%20%2B%20AND%20%E5%AE%8C%E6%88%90%E6%A0%87%E5%BF%97%22%5D%0A%20%20VER%20--%3E%20RECO%0A%20%20RECO%20--%3E%20RESH%5B%22%E6%8C%89%E5%BC%B9%E6%80%A7%E6%9E%9A%E4%B8%BE%E9%80%89%E6%96%B0%E4%B8%96%E7%95%8C%E5%A4%A7%E5%B0%8F%2C%20%E9%87%8D%E5%88%87%E5%88%86%E7%89%87%22%5D%0A%20%20RESH%20--%3E%20WARM%5B%22%E7%A9%BA%E6%AD%A5%E9%A2%84%E7%83%AD%2C%20%E5%86%8D%E5%9B%9E%E5%85%A8%E9%80%9F%22%5D%0A%20%20WARM%20--%3E%20LOG%5B%22%E8%AE%B0%E8%B4%A6%3A%20%E4%B8%A2%E5%A4%B1%E7%AA%97%E5%8F%A3%E4%B8%8E%E4%BA%8B%E4%BB%B6%E4%BA%94%E5%88%97%E5%85%A5%E5%8F%B0%E8%B4%A6%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>检查点 I/O 与分片写读的工程见 <a href="/llm/checkpoint-io-bandwidth">检查点 I/O 带宽</a>；静默损坏的机理与 Xid 口径见 <a href="/llm/gpu-failure-modes">GPU 故障模式</a>；活着的尾延迟归性能课，本课只管「从坏到好」。弹性不是免费：每次重配置的吞吐代价与数值路径重验都要入账，频繁弹性说明故障率估计本身错了。账目化的最后一件小事：恢复演练要定期做——没有演练过的恢复流程，按未经验证的代码算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>容错是四段链路：检测（分域超时）、隔离（退役坏槽）、恢复（AND 快照加重切）、记账（五列入台账）。</li><li>丢失窗口由检查点间隔决定；最优间隔是有效算力的极大值点，随 MTBF 与存储带宽移动。</li><li>弹性世界大小是离散集：EP、TP、PP 的整除约束定格点，选最大可行值，宁可闲置不可破约束。</li><li>恢复后先预热再全速，否则利用率曲线误报二次故障。</li><li>出处：Athlur 等，Varuna，EuroSys 2022；Jiang 等，MegaScale，2024；PyTorch Elastic 的重启语义。</li></ul>',4))])}const T=n(D,[["render",C]]);export{f as __pageData,T as default};
